import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import Header from './components/Header/Header';
import Footer from './components/Footer/Footer';
import ForumPage from './components/Forum/ForumPage';
import ForumDetail from './components/Forum/ForumDetail';
import SubForumDetail from './components/Forum/SubForumDetail';
import ThreadDetail from './components/Thread/ThreadDetail';


function App() {
  const [forums, setForums] = useState([]);

  useEffect(() => {
      fetch('/data/forumData.json')
          .then(response => response.json())
          .then(data => setForums(data.forums))
          .catch(error => console.error('Error fetching forum data:', error));
  }, []);

  const allThreads = forums.flatMap(forum => [
      ...forum.threads || [],
      ...forum.subForums.flatMap(subForum => subForum.threads || [])
  ]);

  return (
      <Router>
          <Header />
          <main style={{ padding: '20px' }}>
              <Routes>
                  <Route path="/" element={<ForumPage forums={forums} />} />
                  <Route path="/forum/:id" element={<ForumDetail forums={forums} />} />
                  <Route path="/subforum/:id" element={<SubForumDetail subForums={forums.flatMap(forum => forum.subForums)} />} />
                  <Route path="/thread/:id" element={<ThreadDetail threads={allThreads} />} />
              </Routes>
          </main>
          <Footer />
      </Router>
  );
}

export default App;
